def _deg_to_rad(deg):
    return deg * math.pi / 180.0






def kinematic_distance(v0, a, t):
    return v0 * t + 0.5 * a * t * t






def kinematic_velocity(v0, a, t):
    return v0 + a * t






def kinetic_energy(mass, velocity):
    return 0.5 * mass * velocity * velocity






def potential_energy(mass, height, g=9.81):
    return mass * g * height






def momentum(mass, velocity):
    return mass * velocity






def gravitational_force(m1, m2, r):
    return G_CONST * m1 * m2 / (r * r)






def projectile_range(v0, angle_deg, g=9.81):
    theta2 = _deg_to_rad(2.0 * angle_deg)
    return v0 * v0 * math.sin(theta2) / g






def projectile_max_height(v0, angle_deg, g=9.81):
    s = math.sin(_deg_to_rad(angle_deg))
    return v0 * v0 * s * s / (2.0 * g)






def projectile_time(v0, angle_deg, g=9.81):
    return 2.0 * v0 * math.sin(_deg_to_rad(angle_deg)) / g






def work(force, distance, angle_deg=0.0):
    return force * distance * math.cos(_deg_to_rad(angle_deg))






def power(work, time):
    return work / time






def elastic_collision_v1(m1, m2, v1, v2):
    return ((m1 - m2) * v1 + 2.0 * m2 * v2) / (m1 + m2)
